// Invoicing Software for Trend Timbers
// Data Storage and Application State

// Logo data URL
const COMPANY_LOGO = "data:image/jpeg;base64,";

class InvoiceApp {
    constructor() {
        // Company information
        this.companyInfo = {
            name: "Trend Timbers",
            address: "15 Railway Road North",
            city: "Mulgrave",
            state: "NSW",
            postcode: "2756",
            phone: "(02) 4577 5277",
            email: "info@trendtimbers.com.au",
            abn: "69 124 544 412"
        };

        // Load data from localStorage or initialize
        this.loadData();

        // GST settings (always 10% in Australia)
        this.gstRate = 10;
// Current editing document and customer
        this.currentDocument = null;
        this.currentCustomer = null;
        this.isCreatingCustomerFromDocument = false;

        this.init();
    }

    loadData() {
        // Try to load from localStorage
        const savedData = localStorage.getItem('trendTimbersInvoiceData');

        if (savedData) {
            const data = JSON.parse(savedData);
            this.customers = data.customers || [];
            this.quotes = data.quotes || [];
            this.invoices = data.invoices || [];
            this.nextQuoteNumber = data.nextQuoteNumber || 1;
            this.nextInvoiceNumber = data.nextInvoiceNumber || 1;
            this.nextCustomerId = data.nextCustomerId || 1;
            this.pdfSavePath = data.pdfSavePath || null;
        } else {
            // Initialize with default data
            this.customers = [
                {
                    id: 1,
                    name: "John Smith",
                    company: "Smith Construction Pty Ltd",
                    email: "john@smithconstruction.com.au",
                    phone: "0412 345 678",
                    address: "123 Builder Street",
                    city: "Sydney",
                    state: "NSW",
                    postcode: "2000",
                    abn: "12 345 678 901"
                },
                {
                    id: 2,
                    name: "Sarah Johnson",
                    company: "Johnson Carpentry",
                    email: "sarah@johnsoncarpentry.com.au",
                    phone: "0423 456 789",
                    address: "456 Timber Road",
                    city: "Parramatta",
                    state: "NSW",
                    postcode: "2150",
                    abn: "23 456 789 012"
                },
                {
                    id: 3,
                    name: "Michael Chen",
                    company: "Chen Furniture Design",
                    email: "michael@chenfurniture.com.au",
                    phone: "0434 567 890",
                    address: "789 Design Avenue",
                    city: "Penrith",
                    state: "NSW",
                    postcode: "2750",
                    abn: "34 567 890 123"
                }
            ];

            this.quotes = [];
            this.invoices = [];
            this.nextQuoteNumber = 1;
            this.nextInvoiceNumber = 1;
            this.nextCustomerId = 4;
            this.pdfSavePath = null;
        }
    }

    saveData() {
        const data = {
            customers: this.customers,
            quotes: this.quotes,
            invoices: this.invoices,
            nextQuoteNumber: this.nextQuoteNumber,
            nextInvoiceNumber: this.nextInvoiceNumber,
            nextCustomerId: this.nextCustomerId,
            pdfSavePath: this.pdfSavePath
        };
        localStorage.setItem('trendTimbersInvoiceData', JSON.stringify(data));
    }

    init() {
        this.setupEventListeners();
        this.showSection('dashboard');
        this.updateDashboard();
        this.renderCustomers();
        this.renderQuotes();
        this.renderInvoices();

        // Show setup modals on first load
        if (!localStorage.getItem('invoiceNumberSet')) {
            this.showSetInvoiceNumberModal();
        } else if (!this.pdfSavePath) {
            this.showPdfSavePathModal();
        }
    }

    showSetInvoiceNumberModal() {
        const modalBody = `
            <form id="setInvoiceNumberForm" class="form">
                <div class="form-group">
                    <label>Starting Invoice Number</label>
                    <input type="number" id="startingInvoiceNumber" min="1" value="${this.nextInvoiceNumber}" required>
                    <small>This will be the number for your next invoice</small>
                </div>
                <div class="form-actions">
                    <button type="submit" class="btn btn--primary">Set Invoice Number</button>
                </div>
            </form>
        `;

        this.showModal('Set Starting Invoice Number', modalBody);

        document.getElementById('setInvoiceNumberForm').addEventListener('submit', (e) => {
            e.preventDefault();
            const startNum = parseInt(document.getElementById('startingInvoiceNumber').value);
            this.nextInvoiceNumber = startNum;
            localStorage.setItem('invoiceNumberSet', 'true');
            this.saveData();
            this.hideModal();

            // Show PDF path modal next
            if (!this.pdfSavePath) {
                setTimeout(() => this.showPdfSavePathModal(), 300);
            }
        });
    }

    showPdfSavePathModal() {
        const modalBody = `
            <form id="setPdfPathForm" class="form">
                <div class="form-group">
                    <label>PDF Save Location (for reference)</label>
                    <input type="text" id="pdfSavePath" value="${this.pdfSavePath || 'C:\\Users\\' + (window.navigator.userAgent.includes('Windows') ? 'YourName' : '') + '\\Documents\\Trend Timbers\\Invoices'}" required>
                    <small>Enter your preferred folder path for saving PDF invoices</small>
                    <small style="display: block; margin-top: 8px;">Example: C:\Users\Matt\Documents\Trend Timbers\Invoices</small>
                </div>
                <div class="form-actions">
                    <button type="submit" class="btn btn--primary">Save Location</button>
                </div>
            </form>
        `;

        this.showModal('Set PDF Save Location', modalBody);

        document.getElementById('setPdfPathForm').addEventListener('submit', (e) => {
            e.preventDefault();
            this.pdfSavePath = document.getElementById('pdfSavePath').value;
            this.saveData();
            this.hideModal();
            alert('PDF save location set to: ' + this.pdfSavePath);
        });
    }

    setupEventListeners() {
        // Navigation
        document.querySelectorAll('.nav-btn').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const section = e.target.dataset.section;
                this.showSection(section);
            });
        });

        // Quick action buttons
        document.getElementById('newQuoteBtn').addEventListener('click', () => this.createNewDocument('quote'));
        document.getElementById('newInvoiceBtn').addEventListener('click', () => this.createNewDocument('invoice'));
        document.getElementById('addCustomerBtn').addEventListener('click', () => this.showCustomerForm());
        document.getElementById('addQuoteBtn').addEventListener('click', () => this.createNewDocument('quote'));
        document.getElementById('addInvoiceBtn').addEventListener('click', () => this.createNewDocument('invoice'));

        // Modal close
        document.getElementById('modalClose').addEventListener('click', () => this.hideModal());
        document.getElementById('modalContainer').addEventListener('click', (e) => {
            if (e.target.id === 'modalContainer') {
                this.hideModal();
            }
        });

        // Search functionality
        document.getElementById('customerSearch').addEventListener('input', (e) => {
            this.searchCustomers(e.target.value);
        });
        document.getElementById('quoteSearch').addEventListener('input', (e) => {
            this.searchDocuments('quotes', e.target.value);
        });
        document.getElementById('invoiceSearch').addEventListener('input', (e) => {
            this.searchDocuments('invoices', e.target.value);
        });
    }

    // Navigation
    showSection(sectionName) {
        // Update nav buttons
        document.querySelectorAll('.nav-btn').forEach(btn => {
            btn.classList.remove('active');
            if (btn.dataset.section === sectionName) {
                btn.classList.add('active');
            }
        });

        // Show/hide sections
        document.querySelectorAll('.content-section').forEach(section => {
            section.classList.remove('active');
        });
        document.getElementById(sectionName).classList.add('active');

        // Update content based on section
        switch (sectionName) {
            case 'dashboard':
                this.updateDashboard();
                break;
            case 'customers':
                this.renderCustomers();
                break;
            case 'quotes':
                this.renderQuotes();
                break;
            case 'invoices':
                this.renderInvoices();
                break;
        }
    }

    // Dashboard
    updateDashboard() {
        document.getElementById('totalQuotes').textContent = this.quotes.length;
        document.getElementById('totalInvoices').textContent = this.invoices.length;
        document.getElementById('totalCustomers').textContent = this.customers.length;
        this.renderRecentDocuments();
    }

    renderRecentDocuments() {
        const recentQuotes = this.quotes.slice(-5).reverse();
        const recentInvoices = this.invoices.slice(-5).reverse();

        this.renderRecentList('recentQuotes', recentQuotes, 'quote');
        this.renderRecentList('recentInvoices', recentInvoices, 'invoice');
    }

    renderRecentList(containerId, documents, type) {
        const container = document.getElementById(containerId);

        if (documents.length === 0) {
            container.innerHTML = '<p style="text-align: center; color: var(--color-text-secondary); padding: var(--space-32);">No ' + type + 's yet</p>';
            return;
        }

        container.innerHTML = documents.map(doc => {
            const customer = this.customers.find(c => c.id === doc.customerId);
            const customerName = customer ? (customer.company || customer.name) : 'Unknown Customer';

            return `
                <div class="data-item" style="cursor: pointer;" onclick="app.editDocument('${type}s', ${doc.id})">
                    <div class="data-item-content">
                        <div class="data-item-title">${doc.number}</div>
                        <div class="data-item-subtitle">${customerName}</div>
                    </div>
                    <div class="data-item-meta">
                        
                        <span class="data-item-subtitle">${this.formatCurrency(doc.total)}</span>
                    </div>
                </div>
            `;
        }).join('');
    }

    // Customers
    renderCustomers(filtered = null) {
        const container = document.getElementById('customersList');
        const customers = filtered || this.customers;

        if (customers.length === 0) {
            container.innerHTML = '<div class="empty-state"><p>No customers found</p></div>';
            return;
        }

        container.innerHTML = customers.map(customer => {
            return `
                <div class="data-item">
                    <div class="data-item-content">
                        <div class="data-item-title">${customer.name}</div>
                        <div class="data-item-subtitle">${customer.company || 'No company'}</div>
                        <div class="data-item-subtitle">${customer.email || ''}</div>
                    </div>
                    <div class="data-item-actions">
                        <button class="btn btn--small btn--secondary" onclick="app.editCustomer(${customer.id})">Edit</button>
                        <button class="btn btn--small btn--secondary" onclick="app.deleteCustomer(${customer.id})">Delete</button>
                    </div>
                </div>
            `;
        }).join('');
    }

    searchCustomers(query) {
        if (!query.trim()) {
            this.renderCustomers();
            return;
        }

        const filtered = this.customers.filter(customer => {
            const searchStr = `${customer.name} ${customer.company} ${customer.email}`.toLowerCase();
            return searchStr.includes(query.toLowerCase());
        });

        this.renderCustomers(filtered);
    }

    showCustomerForm(customer = null) {
        this.currentCustomer = customer;

        const formTitle = customer ? 'Edit Customer' : 'New Customer';
        const modalBody = `
            <form id="customerForm" class="form">
                <div class="form-group">
                    <label>Customer Name *</label>
                    <input type="text" id="customerName" value="${customer?.name || ''}" required>
                </div>
                <div class="form-group">
                    <label>Company/Business Name</label>
                    <input type="text" id="customerCompany" value="${customer?.company || ''}">
                </div>
                <div class="form-group">
                    <label>Email Address</label>
                    <input type="email" id="customerEmail" value="${customer?.email || ''}">
                </div>
                <div class="form-group">
                    <label>Phone Number</label>
                    <input type="tel" id="customerPhone" value="${customer?.phone || ''}">
                </div>
                <div class="form-group">
                    <label>Street Address</label>
                    <input type="text" id="customerAddress" value="${customer?.address || ''}">
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>City</label>
                        <input type="text" id="customerCity" value="${customer?.city || ''}">
                    </div>
                    <div class="form-group">
                        <label>State</label>
                        <input type="text" id="customerState" value="${customer?.state || 'NSW'}">
                    </div>
                    <div class="form-group">
                        <label>Postcode</label>
                        <input type="text" id="customerPostcode" value="${customer?.postcode || ''}">
                    </div>
                </div>
                <div class="form-group">
                    <label>ABN/Business Number</label>
                    <input type="text" id="customerAbn" value="${customer?.abn || ''}">
                </div>
                <div class="form-actions">
                    <button type="button" class="btn btn--secondary" onclick="app.hideModal()">Cancel</button>
                    <button type="submit" class="btn btn--primary">Save Customer</button>
                </div>
            </form>
        `;

        this.showModal(formTitle, modalBody);

        document.getElementById('customerForm').addEventListener('submit', (e) => {
            e.preventDefault();
            this.saveCustomer();
        });
    }

    saveCustomer() {
        const customerData = {
            name: document.getElementById('customerName').value,
            company: document.getElementById('customerCompany').value,
            email: document.getElementById('customerEmail').value,
            phone: document.getElementById('customerPhone').value,
            address: document.getElementById('customerAddress').value,
            city: document.getElementById('customerCity').value,
            state: document.getElementById('customerState').value,
            postcode: document.getElementById('customerPostcode').value,
            abn: document.getElementById('customerAbn').value
        };

        if (this.currentCustomer) {
            // Update existing customer
            const index = this.customers.findIndex(c => c.id === this.currentCustomer.id);
            this.customers[index] = { ...this.currentCustomer, ...customerData };
        } else {
            // Create new customer
            const newCustomer = {
                id: this.nextCustomerId++,
                ...customerData
            };
            this.customers.push(newCustomer);

            // If creating from document, select this customer
            if (this.isCreatingCustomerFromDocument) {
                const select = document.getElementById('docCustomer');
                if (select) {
                    this.populateCustomerSelect();
                    select.value = newCustomer.id;
                }
                this.isCreatingCustomerFromDocument = false;
            }
        }

        this.saveData();
        this.renderCustomers();
        this.hideModal();
    }

    editCustomer(id) {
        const customer = this.customers.find(c => c.id === id);
        if (customer) {
            this.showCustomerForm(customer);
        }
    }

    deleteCustomer(id) {
        if (confirm('Are you sure you want to delete this customer?')) {
            this.customers = this.customers.filter(c => c.id !== id);
            this.saveData();
            this.renderCustomers();
        }
    }

    // Documents (Quotes & Invoices)
    renderQuotes(filtered = null) {
        this.renderDocuments('quotes', filtered);
    }

    renderInvoices(filtered = null) {
        this.renderDocuments('invoices', filtered);
    }

    renderDocuments(type, filtered = null) {
        const container = document.getElementById(type + 'List');
        const documents = filtered || this[type];

        if (documents.length === 0) {
            container.innerHTML = '<div class="empty-state"><p>No ' + type + ' found</p></div>';
            return;
        }

        const isQuote = type === 'quotes';

        container.innerHTML = documents.map(doc => {
            const customer = this.customers.find(c => c.id === doc.customerId);
            const customerName = customer ? (customer.company || customer.name) : 'Unknown Customer';

            return `
                <div class="data-item">
                    <div class="data-item-content">
                        <div class="data-item-title">${doc.number}</div>
                        <div class="data-item-subtitle">${customerName} • ${doc.date}</div>
                    </div>
                    <div class="data-item-meta">
                        
                        <span class="data-item-subtitle">${this.formatCurrency(doc.total)}</span>
                    </div>
                    <div class="data-item-actions">
                        <button class="btn btn--small btn--secondary" onclick="app.editDocument('${type}', ${doc.id})">Edit</button>
                        <button class="btn btn--small btn--secondary" onclick="app.viewDocument('${type}', ${doc.id})">View PDF</button>
                        ${isQuote ? `<button class="btn btn--small btn--primary" onclick="app.convertQuoteToInvoice(${doc.id})">Convert to Invoice</button>` : ''}
                        <button class="btn btn--small btn--secondary" onclick="app.deleteDocument('${type}', ${doc.id})">Delete</button>
                    </div>
                </div>
            `;
        }).join('');
    }

    searchDocuments(type, query) {
        if (!query.trim()) {
            this.renderDocuments(type);
            return;
        }

        const filtered = this[type].filter(doc => {
            const customer = this.customers.find(c => c.id === doc.customerId);
            const customerName = customer ? `${customer.name} ${customer.company}` : '';
            const searchStr = `${doc.number} ${customerName}`.toLowerCase();
            return searchStr.includes(query.toLowerCase());
        });

        this.renderDocuments(type, filtered);
    }

    createNewDocument(type) {
        const isInvoice = type === 'invoice';
        const number = isInvoice ? 
            `INV-${String(this.nextInvoiceNumber).padStart(4, '0')}` : 
            `QUO-${String(this.nextQuoteNumber).padStart(4, '0')}`;

        const today = new Date().toISOString().split('T')[0];

        this.currentDocument = {
            type: type,
            id: null,
            number: number,
            date: today,
            customerId: null,
            lineItems: [],
            notes: '',
            subtotal: 0,
            gstTotal: 0,
            gstFree: 0,
            total: 0
        };

        this.showDocumentForm();
    }

    editDocument(type, id) {
        const doc = this[type].find(d => d.id === id);
        if (doc) {
            this.currentDocument = { ...doc, type: type.replace('s', '') };
            this.showDocumentForm();
        }
    }

    viewDocument(type, id) {
        const doc = this[type].find(d => d.id === id);
        if (doc) {
            this.currentDocument = { ...doc, type: type.replace('s', '') };
            this.generatePDF();
        }
    }

    deleteDocument(type, id) {
        if (confirm(`Are you sure you want to delete this ${type.slice(0, -1)}?`)) {
            this[type] = this[type].filter(d => d.id !== id);
            this.saveData();
            this.renderDocuments(type);
            this.updateDashboard();
        }
    }

    convertQuoteToInvoice(quoteId) {
        const quote = this.quotes.find(q => q.id === quoteId);
        if (!quote) return;

        if (!confirm(`Convert quote ${quote.number} to an invoice?`)) return;

        // Create new invoice from quote
        const newInvoice = {
            ...quote,
            type: 'invoice',
            id: Date.now(),
            number: `INV-${String(this.nextInvoiceNumber).padStart(4, '0')}`,
            date: new Date().toISOString().split('T')[0]
        };

        this.invoices.push(newInvoice);
        this.nextInvoiceNumber++;

        // Update quote status
        const quoteIndex = this.quotes.findIndex(q => q.id === quoteId);
        this.quotes[quoteIndex].status = 'Accepted';

        this.saveData();
        this.renderQuotes();
        this.renderInvoices();
        this.updateDashboard();

        alert(`Quote ${quote.number} converted to invoice ${newInvoice.number}`);
    }

    showDocumentForm() {
        const doc = this.currentDocument;
        const isInvoice = doc.type === 'invoice';
        const title = doc.id ? `Edit ${isInvoice ? 'Invoice' : 'Quote'}` : `New ${isInvoice ? 'Invoice' : 'Quote'}`;

        const modalBody = `
            <form id="documentForm" class="form document-form">
                <div class="form-row">
                    <div class="form-group">
                        <label>Document Number</label>
                        <input type="text" id="docNumber" value="${doc.number}" readonly>
                    </div>
                    <div class="form-group">
                        <label>Date *</label>
                        <input type="date" id="docDate" value="${doc.date}" required>
                    </div>
                </div>

                <div class="form-group">
                    <label>Customer *</label>
                    <div class="customer-selection">
                        <select id="docCustomer" class="customer-select" required>
                            <option value="">Select a customer...</option>
                            ${this.customers.map(c => 
                                `<option value="${c.id}" ${doc.customerId === c.id ? 'selected' : ''}>${c.company || c.name}</option>`
                            ).join('')}
                        </select>
                        <button type="button" class="btn btn--secondary" onclick="app.createCustomerFromDocument()">Add New Customer</button>
                    </div>
                </div>

                <div class="form-group">
                    
                </div>

                <div class="line-items-section">
                    <h4>Line Items</h4>
                    <div class="line-items-header">
                        <div style="flex: 2;">Description</div>
                        <div style="width: 80px; text-align: center;">Qty</div>
                        <div style="width: 100px; text-align: right;">Unit Price</div>
                        <div style="width: 80px; text-align: center;">GST</div>
                        <div style="width: 100px; text-align: right;">Total</div>
                        <div style="width: 40px;"></div>
                    </div>
                    <div id="lineItemsContainer" class="line-items-container">
                        ${this.renderLineItems()}
                    </div>
                    <button type="button" class="btn btn--secondary" onclick="app.addLineItem()">Add Line Item</button>
                </div>

                <div class="form-totals">
                    <div class="total-row">
                        <span>Subtotal:</span>
                        <span id="docSubtotal">${this.formatCurrency(doc.subtotal)}</span>
                    </div>
                    <div class="total-row">
                        <span>GST on exc GST items (10%):</span>
                        <span id="docGst">${this.formatCurrency(doc.gstTotal)}</span>
                    </div>
                    <div class="total-row">
                        <span>GST-included items:</span>
                        <span id="docGstFree">${this.formatCurrency(doc.gstFree)}</span>
                    </div>
                    <div class="total-row total-row-final">
                        <span>Total Amount Due:</span>
                        <span id="docTotal">${this.formatCurrency(doc.total)}</span>
                    </div>
                </div>

                <div class="form-group">
                    <label>Notes/Terms</label>
                    <textarea id="docNotes" rows="4">${doc.notes || ''}</textarea>
                </div>

                <div class="form-actions">
                    <button type="button" class="btn btn--secondary" onclick="app.hideModal()">Cancel</button>
                    <button type="submit" class="btn btn--primary">Save Document</button>
                    <button type="button" class="btn btn--secondary" onclick="app.generatePDF()">Generate PDF</button>
                    <button type="button" class="btn btn--secondary" onclick="app.emailViaOutlook()">Email via Outlook</button>
                </div>
            </form>
        `;

        this.showModal(title, modalBody);

        document.getElementById('documentForm').addEventListener('submit', (e) => {
            e.preventDefault();
            this.saveDocument();
        });

        // Initialize line items if empty
        if (!doc.lineItems || doc.lineItems.length === 0) {
            this.addLineItem();
        }
    }

    createCustomerFromDocument() {
        this.isCreatingCustomerFromDocument = true;
        this.showCustomerForm();
    }

    populateCustomerSelect() {
        const select = document.getElementById('docCustomer');
        if (!select) return;

        select.innerHTML = `
            <option value="">Select a customer...</option>
            ${this.customers.map(c => 
                `<option value="${c.id}">${c.company || c.name}</option>`
            ).join('')}
        `;
    }

    renderLineItems() {
        if (!this.currentDocument.lineItems || this.currentDocument.lineItems.length === 0) {
            return '';
        }

        return this.currentDocument.lineItems.map((item, index) => {
            const lineTotal = item.quantity * item.unitPrice;
            return `
                <div class="line-item" data-index="${index}" style="display: flex; gap: 12px; align-items: center; margin-bottom: 12px;">
                    <input type="text" style="flex: 2; padding: 8px; border: 1px solid var(--color-border); border-radius: 6px;" 
                           value="${item.description}" 
                           onchange="app.updateLineItem(${index}, 'description', this.value)" 
                           placeholder="Description">
                    <input type="number" style="width: 80px; padding: 8px; border: 1px solid var(--color-border); border-radius: 6px; text-align: center;" 
                           value="${item.quantity}" min="0" step="0.01"
                           onchange="app.updateLineItem(${index}, 'quantity', this.value)">
                    <input type="number" style="width: 100px; padding: 8px; border: 1px solid var(--color-border); border-radius: 6px; text-align: right;" 
                           value="${item.unitPrice}" min="0" step="0.01"
                           onchange="app.updateLineItem(${index}, 'unitPrice', this.value)">
                    <label style="width: 80px; display: flex; align-items: center; justify-content: center; gap: 4px; cursor: pointer;">
                        <input type="checkbox" ${item.gstIncluded ? 'checked' : ''}
                               onchange="app.updateLineItem(${index}, 'gstIncluded', this.checked)">
                        <span style="font-size: 12px;">${item.gstIncluded ? 'inc' : 'exc'}</span>
                    </label>
                    <div style="width: 100px; text-align: right; font-weight: 500; padding: 8px;">${this.formatCurrency(lineTotal)}</div>
                    <button type="button" class="btn btn--small btn--secondary" style="width: 40px; height: 32px; padding: 0; display: flex; align-items: center; justify-content: center;" 
                            onclick="app.removeLineItem(${index})">&times;</button>
                </div>
            `;
        }).join('');
    }

    addLineItem() {
        if (!this.currentDocument.lineItems) {
            this.currentDocument.lineItems = [];
        }

        this.currentDocument.lineItems.push({
            description: '',
            quantity: 1,
            unitPrice: 0,
            gstIncluded: false
        });

        this.refreshLineItems();
    }

    updateLineItem(index, field, value) {
        if (!this.currentDocument.lineItems[index]) return;

        if (field === 'quantity' || field === 'unitPrice') {
            value = parseFloat(value) || 0;
        } else if (field === 'gstIncluded') {
            // Update the label next to the checkbox
            const lineItem = document.querySelector(`[data-index="${index}"]`);
            if (lineItem) {
                const label = lineItem.querySelector('label span');
                if (label) {
                    label.textContent = value ? 'inc' : 'exc';
                }
            }
        }

        this.currentDocument.lineItems[index][field] = value;
        this.calculateTotals();
    }

    removeLineItem(index) {
        this.currentDocument.lineItems.splice(index, 1);
        this.refreshLineItems();
    }

    refreshLineItems() {
        const container = document.getElementById('lineItemsContainer');
        if (container) {
            container.innerHTML = this.renderLineItems();
            this.calculateTotals();
        }
    }

    calculateTotals() {
        let subtotal = 0;
        let gstOnExcItems = 0;
        let gstIncludedItems = 0;

        this.currentDocument.lineItems.forEach(item => {
            const lineTotal = item.quantity * item.unitPrice;

            if (item.gstIncluded) {
                // GST is included in the price
                gstIncludedItems += lineTotal;
                subtotal += lineTotal;
            } else {
                // GST needs to be added
                subtotal += lineTotal;
                gstOnExcItems += lineTotal * (this.gstRate / 100);
            }
        });

        this.currentDocument.subtotal = subtotal;
        this.currentDocument.gstTotal = gstOnExcItems;
        this.currentDocument.gstFree = gstIncludedItems;
        this.currentDocument.total = subtotal + gstOnExcItems;

        // Update display
        const subtotalEl = document.getElementById('docSubtotal');
        const gstEl = document.getElementById('docGst');
        const gstFreeEl = document.getElementById('docGstFree');
        const totalEl = document.getElementById('docTotal');

        if (subtotalEl) subtotalEl.textContent = this.formatCurrency(subtotal);
        if (gstEl) gstEl.textContent = this.formatCurrency(gstOnExcItems);
        if (gstFreeEl) gstFreeEl.textContent = this.formatCurrency(gstIncludedItems);
        if (totalEl) totalEl.textContent = this.formatCurrency(subtotal + gstOnExcItems);

        // Update line totals
        this.currentDocument.lineItems.forEach((item, index) => {
            const lineTotal = item.quantity * item.unitPrice;
            const lineTotalEl = document.querySelector(`[data-index="${index}"] div[style*="width: 100px; text-align: right"]`);
            if (lineTotalEl) {
                lineTotalEl.textContent = this.formatCurrency(lineTotal);
            }
        });
    }

    saveDocument() {
        // Get form values
        const doc = this.currentDocument;
        doc.date = document.getElementById('docDate').value;
        doc.customerId = parseInt(document.getElementById('docCustomer').value);
doc.notes = document.getElementById('docNotes').value;

        if (!doc.customerId) {
            alert('Please select a customer');
            return;
        }

        // Save to appropriate array
        const type = doc.type + 's'; // 'invoice' -> 'invoices', 'quote' -> 'quotes'

        if (doc.id) {
            // Update existing document
            const index = this[type].findIndex(d => d.id === doc.id);
            if (index !== -1) {
                this[type][index] = doc;
            }
        } else {
            // Create new document
            doc.id = Date.now(); // Simple unique ID

            // Increment the counter for next time
            if (doc.type === 'invoice') {
                this.nextInvoiceNumber++;
            } else {
                this.nextQuoteNumber++;
            }

            this[type].push(doc);
        }

        // Save to localStorage
        this.saveData();

        // Update UI
        this.renderDocuments(type);
        this.updateDashboard();

        alert(`${doc.type === 'invoice' ? 'Invoice' : 'Quote'} saved successfully!`);
    }

    async generatePDF() {
        if (!this.currentDocument) return;

        // Update current form state
        const form = document.getElementById('documentForm');
        if (form) {
            this.currentDocument.date = document.getElementById('docDate').value;
            this.currentDocument.customerId = parseInt(document.getElementById('docCustomer').value) || this.currentDocument.customerId;
this.currentDocument.notes = document.getElementById('docNotes').value;
        }

        const doc = this.currentDocument;
        const customer = this.customers.find(c => c.id === doc.customerId);

        if (!customer) {
            alert('Please select a customer before generating PDF');
            return;
        }

        const isInvoice = doc.type === 'invoice';
        const docTitle = isInvoice ? 'TAX INVOICE' : 'QUOTE';

        // Build line items HTML
        let lineItemsHTML = '';
        doc.lineItems.forEach(item => {
            const lineTotal = item.quantity * item.unitPrice;
            const gstLabel = item.gstIncluded ? 'inc GST' : 'exc GST';
            lineItemsHTML += `
                <tr>
                    <td>${item.description}</td>
                    <td style="text-align: center;">${item.quantity}</td>
                    <td style="text-align: right;">${this.formatCurrency(item.unitPrice)}</td>
                    <td style="text-align: center;">${gstLabel}</td>
                    <td style="text-align: right;">${this.formatCurrency(lineTotal)}</td>
                </tr>
            `;
        });

        // Create PDF HTML
        const pdfHTML = `
            <!DOCTYPE html>
            <html>
            <head>
                <meta charset="UTF-8">
                <style>
                    * {
                        margin: 0;
                        padding: 0;
                        box-sizing: border-box;
                    }
                    body {
                        font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                        font-size: 10pt;
                        line-height: 1.4;
                        color: #333;
                        padding: 20px;
                        background: white;
                    }
                    .invoice {
                        max-width: 750px;
                        margin: 0 auto;
                    }
                    .header {
                        display: flex;
                        justify-content: space-between;
                        align-items: flex-start;
                        margin-bottom: 30px;
                        padding-bottom: 20px;
                        border-bottom: 3px solid #055902;
                    }
                    .logo {
                        max-width: 180px;
                        height: auto;
                    }
                    .company-info {
                        text-align: right;
                        line-height: 1.6;
                    }
                    .company-name {
                        font-size: 16pt;
                        font-weight: bold;
                        color: #055902;
                        margin-bottom: 5px;
                    }
                    .invoice-title {
                        font-size: 22pt;
                        font-weight: bold;
                        color: #055902;
                        margin: 20px 0;
                        text-align: right;
                    }
                    .invoice-details {
                        display: flex;
                        justify-content: space-between;
                        margin-bottom: 30px;
                    }
                    .bill-to, .invoice-meta {
                        flex: 1;
                    }
                    .section-title {
                        font-weight: bold;
                        font-size: 11pt;
                        margin-bottom: 10px;
                        color: #055902;
                    }
                    table {
                        width: 100%;
                        border-collapse: collapse;
                        margin: 20px 0;
                    }
                    th {
                        background: #055902;
                        color: white;
                        padding: 10px;
                        text-align: left;
                        font-weight: 600;
                    }
                    td {
                        padding: 10px;
                        border-bottom: 1px solid #ddd;
                    }
                    tr:last-child td {
                        border-bottom: none;
                    }
                    .totals {
                        margin-top: 20px;
                        margin-left: auto;
                        width: 300px;
                    }
                    .total-row {
                        display: flex;
                        justify-content: space-between;
                        padding: 8px 0;
                        border-bottom: 1px solid #eee;
                    }
                    .total-row.final {
                        font-weight: bold;
                        font-size: 14pt;
                        color: #055902;
                        border-top: 2px solid #055902;
                        border-bottom: 3px double #055902;
                        margin-top: 10px;
                        padding-top: 15px;
                    }
                    .notes {
                        margin-top: 40px;
                        padding: 15px;
                        background: #f9f9f9;
                        border-left: 3px solid #055902;
                    }
                    .footer {
                        margin-top: 40px;
                        padding-top: 20px;
                        border-top: 1px solid #ddd;
                        text-align: center;
                        font-size: 9pt;
                        color: #666;
                    }
                </style>
            </head>
            <body>
                <div class="invoice">
                    <div class="header">
                        <img src="${COMPANY_LOGO}" alt="${this.companyInfo.name}" class="logo">
                        <div class="company-info">
                            <div class="company-name">${this.companyInfo.name}</div>
                            <div>${this.companyInfo.address}</div>
                            <div>${this.companyInfo.city}, ${this.companyInfo.state} ${this.companyInfo.postcode}</div>
                            <div>ABN: ${this.companyInfo.abn}</div>
                            <div>${this.companyInfo.phone}</div>
                            <div>${this.companyInfo.email}</div>
                        </div>
                    </div>

                    <div class="invoice-title">${docTitle}</div>

                    <div class="invoice-details">
                        <div class="bill-to">
                            <div class="section-title">BILL TO:</div>
                            <div><strong>${customer.name}</strong></div>
                            ${customer.company ? `<div>${customer.company}</div>` : ''}
                            ${customer.address ? `<div>${customer.address}</div>` : ''}
                            ${customer.city ? `<div>${customer.city}, ${customer.state} ${customer.postcode}</div>` : ''}
                            ${customer.email ? `<div>${customer.email}</div>` : ''}
                            ${customer.phone ? `<div>${customer.phone}</div>` : ''}
                            ${customer.abn ? `<div>ABN: ${customer.abn}</div>` : ''}
                        </div>
                        <div class="invoice-meta" style="text-align: right;">
                            <div class="section-title">${isInvoice ? 'INVOICE' : 'QUOTE'} DETAILS:</div>
                            <div><strong>${isInvoice ? 'Invoice' : 'Quote'} #:</strong> ${doc.number}</div>
                            <div><strong>Date:</strong> ${this.formatDate(doc.date)}</div>
                            </div>
                    </div>

                    <table>
                        <thead>
                            <tr>
                                <th>Description</th>
                                <th style="text-align: center; width: 80px;">Qty</th>
                                <th style="text-align: right; width: 100px;">Unit Price</th>
                                <th style="text-align: center; width: 80px;">GST</th>
                                <th style="text-align: right; width: 100px;">Total</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${lineItemsHTML}
                        </tbody>
                    </table>

                    <div class="totals">
                        <div class="total-row">
                            <span>Subtotal:</span>
                            <span>${this.formatCurrency(doc.subtotal)}</span>
                        </div>
                        ${doc.gstTotal > 0 ? `
                            <div class="total-row">
                                <span>GST on exc GST items (10%):</span>
                                <span>${this.formatCurrency(doc.gstTotal)}</span>
                            </div>
                        ` : ''}
                        ${doc.gstFree > 0 ? `
                            <div class="total-row">
                                <span>GST-included items:</span>
                                <span>${this.formatCurrency(doc.gstFree)}</span>
                            </div>
                        ` : ''}
                        <div class="total-row final">
                            <span>TOTAL AMOUNT DUE:</span>
                            <span>${this.formatCurrency(doc.total)}</span>
                        </div>
                    </div>

                    ${doc.notes ? `
                        <div class="notes">
                            <div class="section-title">NOTES/TERMS:</div>
                            <div>${doc.notes.replace(/\n/g, '<br>')}</div>
                        </div>
                    ` : ''}

                    <div class="footer">
						<div style="margin-bottom: 20px; padding-bottom: 20px; border-bottom: 1px solid #ddd;">
							<p style="font-weight: bold; font-size: 11pt; margin-bottom: 10px; color: #055902;">DIRECT DEPOSIT</p>
							<p style="margin: 5px 0;"><strong>WESTPAC</strong></p>
							<p style="margin: 3px 0;">Account Name: RB & AJ Clark PTY LTD</p>
							<p style="margin: 3px 0;">BSB: 032274</p>
							<p style="margin: 3px 0;">A/C: 249387</p>
						</div>
							<p style="margin-top: 15px;">Thank you for your business!</p>
							<p>${this.companyInfo.name} • ${this.companyInfo.phone} • ${this.companyInfo.email}</p>
				</div>

                </div>
            </body>
            </html>
        `;

        // Render HTML to hidden container
        const container = document.getElementById('pdfContainer');
        container.innerHTML = pdfHTML;

        try {
            // Wait for images to load
            await new Promise(resolve => setTimeout(resolve, 500));

            // Use html2canvas to capture the invoice
            const canvas = await html2canvas(container.querySelector('.invoice'), {
                scale: 1,
                useCORS: true,
                logging: false,
                backgroundColor: '#ffffff'
            });

            const imgData = canvas.toDataURL('image/png');

            // Create PDF
            const { jsPDF } = window.jspdf;
            const pdf = new jsPDF({
                orientation: 'portrait',
                unit: 'mm',
                format: 'a4'
            });

            const pageWidth = pdf.internal.pageSize.getWidth();
            const pageHeight = pdf.internal.pageSize.getHeight();
            const imgWidth = pageWidth - 20; // 10mm margins
            const imgHeight = (canvas.height * imgWidth) / canvas.width;

            pdf.addImage(imgData, 'PNG', 10, 10, imgWidth, Math.min(imgHeight, pageHeight - 20));

            // Generate filename
            const customerName = customer.company || customer.name;
            const fileName = `${doc.number} - ${customerName}.pdf`;

            // Save the PDF
            pdf.save(fileName);

            // Clear container
            container.innerHTML = '';

            alert(`PDF saved as: ${fileName}`);
        } catch (error) {
            console.error('PDF generation error:', error);
            alert('Error generating PDF. Please check the console for details.');
        }
    }

    async emailViaOutlook() {
        if (!this.currentDocument) return;

        // Update the document with current form values
        const form = document.getElementById('documentForm');
        if (form) {
            this.currentDocument.date = document.getElementById('docDate').value;
            this.currentDocument.customerId = parseInt(document.getElementById('docCustomer').value) || this.currentDocument.customerId;
this.currentDocument.notes = document.getElementById('docNotes').value;
        }

        const doc = this.currentDocument;
        const customer = this.customers.find(c => c.id === doc.customerId);

        if (!customer) {
            alert('Please select a customer before emailing');
            return;
        }

        if (!customer.email) {
            alert('This customer does not have an email address. Please add one first.');
            return;
        }

        const isInvoice = doc.type === 'invoice';
        const docType = isInvoice ? 'Invoice' : 'Quote';

        // Generate and WAIT for the PDF to save
        await this.generatePDF();

        // Create email subject and body
        const subject = `${docType} ${doc.number} from ${this.companyInfo.name}`;
        const body = `Hi ${customer.name},

Please find attached ${docType} ${doc.number} for ${this.formatCurrency(doc.total)}.

${doc.notes ? 'Notes:\n' + doc.notes + '\n\n' : ''}If you have any questions, please don't hesitate to contact us.

Thank you for your business!

${this.companyInfo.name}
${this.companyInfo.phone}
${this.companyInfo.email}`;

        // Create mailto link
        const mailtoLink = `mailto:${customer.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;

        // Get the filename
        const customerName = customer.company || customer.name;
        const fileName = `${doc.number} - ${customerName}.pdf`;

        // Show instruction to user
        alert(`PDF saved to your Downloads folder as:\n"${fileName}"\n\nOutlook Classic will now open.\nPlease attach the PDF file manually before sending.`);

        // Open Outlook Classic
        window.location.href = mailtoLink;
    }

    // Modal
    showModal(title, body) {
        document.getElementById('modalTitle').textContent = title;
        document.getElementById('modalBody').innerHTML = body;
        document.getElementById('modalContainer').classList.remove('hidden');
    }

    hideModal() {
        document.getElementById('modalContainer').classList.add('hidden');
    }

    // Utility functions
    formatCurrency(amount) {
        return new Intl.NumberFormat('en-AU', {
            style: 'currency',
            currency: 'AUD'
        }).format(amount || 0);
    }

    formatDate(dateStr) {
        const date = new Date(dateStr);
        return date.toLocaleDateString('en-AU', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    }
}

// Initialize app
let app;
document.addEventListener('DOMContentLoaded', () => {
    app = new InvoiceApp();
});
